<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Models\{DownloadToken,InstallationEvent,Release}; use App\Services\ApiResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage; use Illuminate\Support\Str;
class PackageController extends Controller { public function token(Request $request){$data=$request->validate(['release_id'=>'required|uuid']);$installation=$request->attributes->get('installation');$release=Release::where('uuid',$data['release_id'])->where('product_id',$installation->product_id)->where('status','published')->first();if(!$release||!$release->package_path)return ApiResponse::error('RELEASE_NOT_AVAILABLE','Release package is not available.',404);$raw='odt_'.Str::random(64);DownloadToken::create(['token_hash'=>hash('sha256',$raw),'installation_id'=>$installation->id,'release_id'=>$release->id,'expires_at'=>now()->addSeconds(config('office.download_token_lifetime_seconds'))]);return ApiResponse::ok(['download_url'=>rtrim(config('office.public_url'),'/').'/api/v1/packages/download/'.$raw,'expires_at'=>now()->addSeconds(config('office.download_token_lifetime_seconds'))->toISOString(),'sha256'=>$release->package_sha256,'size'=>$release->package_size]);} public function download(string $token){$record=DownloadToken::with('release')->where('token_hash',hash('sha256',$token))->whereNull('used_at')->where('expires_at','>',now())->first();if(!$record)return ApiResponse::error('PACKAGE_NOT_FOUND','Download token is invalid or expired.',404);$record->update(['used_at'=>now()]);InstallationEvent::create(['installation_id'=>$record->installation_id,'type'=>'package_downloaded','context'=>['release_id'=>$record->release_id],'occurred_at'=>now()]);return Storage::disk(config('office.package_disk'))->download($record->release->package_path,$record->release->package_filename,['Digest'=>'sha-256='.$record->release->package_sha256]);} }
